"""Six publication figures; numerical traces are generated by run.py."""

from pathlib import Path
import argparse, json
import numpy as np
from visual_style import setup, style, panel, save, plt, INK, MUTED, GRID

ROOT = Path(__file__).resolve().parents[2]
COL = ["#2471A3", "#15958B", "#D18429"]
METHOD = ["lowpass", "optimizer", "qlearning"]
LABEL = ["低通规则", "单步优化", "Q学习"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument(
        "--source", type=Path, default=ROOT / "results/ch07/experiment.json"
    )
    ap.add_argument("--out", type=Path, default=ROOT / "assets/ch07")
    ap.add_argument("--font")
    a = ap.parse_args()
    setup(a.font)
    e = json.loads(a.source.read_text(encoding="utf-8"))
    out = a.out

    def trace(s, m, k):
        return np.array([r[k] for r in e["traces"][s + "/" + m]])

    t = trace("nominal", "lowpass", "time_s")
    fig, ax = plt.subplots(1, 2, figsize=(8, 3.8), layout="constrained")
    v = np.linspace(0, 160, 400)
    en = 450 * v * v / 7.2e6
    ax[0].plot(v, en, c=COL[1], lw=2.4)
    ax[0].fill_between(v, en, where=v >= 80, color=COL[1], alpha=0.14)
    ax[0].axvline(80, c=MUTED, ls="--", lw=0.8)
    ax[0].axhline(0.4, c=MUTED, ls=":", lw=0.8)
    ax[0].scatter([80, 160], [0.4, 1.6], c=COL[1], zorder=5)
    ax[0].annotate(
        "可用能量 1.20 kWh",
        xy=(120, 0.9),
        xytext=(30, 1.4),
        arrowprops=dict(arrowstyle="->", color=MUTED),
        fontsize=10,
    )
    ax[0].set(
        xlabel="超级电容电压 / V", ylabel="内部储能 / kWh", xlim=(0, 170), ylim=(0, 1.8)
    )
    panel(ax[0], "(a)", "电压的平方决定储能")
    style(ax[0])
    frac = np.linspace(0, 1, 100)
    ax[1].plot(frac, 80 + 80 * frac, "--", color=MUTED, label="电压线性插值")
    ax[1].plot(
        frac,
        np.sqrt((0.4 + 1.2 * frac) * 7.2e6 / 450),
        c=COL[1],
        lw=2.4,
        label="可用能量比例",
    )
    ax[1].scatter([0.5], [np.sqrt(16000)], c=COL[1])
    ax[1].annotate(
        "50% 可用能量\n126.5 V",
        (0.5, 126.5),
        (0.10, 141),
        arrowprops=dict(arrowstyle="->", color=MUTED),
        fontsize=10,
    )
    ax[1].set(xlabel="可用能量比例", ylabel="电压 / V", ylim=(76, 164))
    ax[1].legend(loc="lower right", frameon=False, fontsize=8.7)
    style(ax[1])
    panel(ax[1], "(b)", "两种归一化量的区别")
    save(fig, out, "fig7_03_voltage_energy")
    fig, axs = plt.subplots(3, 1, figsize=(8, 6), sharex=True, layout="constrained")
    d = trace("nominal", "lowpass", "demand_kw")
    b = trace("nominal", "lowpass", "battery_kw")
    s = trace("nominal", "lowpass", "sc_kw")
    for ax, y, col, lab in zip(
        axs,
        [d, b, s],
        [INK, COL[0], COL[1]],
        ["(a) 共同功率需求", "(b) 电池承担缓慢分量", "(c) 超级电容承担快速分量"],
    ):
        ax.plot(t[:180], y[:180], c=col, lw=1.25)
        ax.axhline(0, c=MUTED, lw=0.5)
        ax.set(ylabel="功率 / kW", ylim=(-90, 115))
        panel(ax, "", lab)
        style(ax)
    axs[-1].set_xlabel("时间 / s")
    save(fig, out, "fig7_05_lowpass")
    fig, axs = plt.subplots(3, 1, figsize=(8, 6.2), sharex=True, layout="constrained")
    for m, l, col in zip(METHOD, LABEL, COL):
        for ax, key in zip(axs, ["battery_kw", "sc_kwh", "residual_kw"]):
            ax.plot(t, trace("nominal", m, key), c=col, lw=1.25, label=l)
    for ax, label, title in zip(
        axs,
        ["电池功率 / kW", "超级电容能量 / kWh", "残差功率 / kW"],
        ["(a) 相同输入下的电池功率", "(b) 储能轨迹与物理上下界", "(c) 全时段功率残差"],
    ):
        ax.set_ylabel(label)
        panel(ax, "", title)
        style(ax)
    axs[1].axhline(0.4, c=MUTED, ls="--", lw=0.8)
    axs[1].axhline(1.6, c=MUTED, ls="--", lw=0.8)
    axs[1].set_ylim(0.3, 1.7)
    axs[0].legend(
        ncol=3, frameon=False, loc="lower right", bbox_to_anchor=(1, 1.02), fontsize=8.6
    )
    axs[-1].set_xlabel("时间 / s")
    save(fig, out, "fig7_06_controller_traces")
    fig, ax = plt.subplots(1, 2, figsize=(8, 4), layout="constrained")
    cc = ["#2471A3", "#15958B", "#D18429", "#9365A6", "#596E82"]
    for seed, col in zip(e["train_seeds"], cc):
        h = [r for r in e["training"] if r["training_seed"] == seed]
        ax[0].plot(
            [r["episode"] for r in h],
            [r["validation_cost"] for r in h],
            "-o",
            c=col,
            lw=1.3,
            ms=3,
            label=str(seed),
        )
        sel = next(r for r in e["selection"] if r["training_seed"] == seed)
        ax[0].scatter(
            sel["selected_episode"],
            sel["validation_cost"],
            c=col,
            marker="*",
            s=100,
            zorder=5,
        )
    ax[0].set(xlabel="训练回合", ylabel="验证集平均单步代价")
    ax[0].set_ylim(0.2, 2.35)
    ax[0].legend(
        title="训练种子",
        ncol=3,
        fontsize=8,
        frameon=False,
        title_fontsize=8,
        loc="upper right",
    )
    panel(ax[0], "(a)", "用验证集选择检查点")
    style(ax[0])
    q = np.array(e["selected_q"])
    action = np.array([-20, -10, -5, 0, 5, 10, 20])
    z = action[np.argmax(q[:, :, 4, :], axis=-1)].T
    im = ax[1].imshow(z, origin="lower", cmap="BrBG", vmin=-20, vmax=20, aspect="auto")
    ax[1].set(
        xlabel="需求功率离散区间",
        ylabel="可用能量比例离散区间",
        xticks=[0, 2, 4, 6, 8],
        yticks=[0, 2, 4, 6, 8],
    )
    panel(ax[1], "(b)", "冻结策略的动作切片")
    cb = fig.colorbar(im, ax=ax[1], shrink=0.8)
    cb.set_label("电池功率增量 / kW")
    ax[1].text(
        0.5,
        -0.21,
        "上一时刻电池功率区间：−5～5 kW",
        transform=ax[1].transAxes,
        ha="center",
        fontsize=8.4,
        color=MUTED,
    )
    save(fig, out, "fig7_07_learning")
    fig, axs = plt.subplots(1, 3, figsize=(9, 4.2), layout="constrained")
    keys = ["rmse_kw", "battery_throughput_kwh", "sc_endpoint_kwh"]
    yl = ["残差 RMSE / kW", "电池吞吐量 / kWh", "超级电容端点偏移 / kWh"]
    for ax, key, ylabel, letter in zip(axs, keys, yl, ["(a)", "(b)", "(c)"]):
        data = []
        for m in METHOD:
            rows = [
                r
                for r in e["metrics"]
                if r["scenario"] == "nominal" and r["method"] == m
            ]
            # Independent scenario seeds are the paired statistical units.
            data.append(
                [
                    np.mean([r[key] for r in rows if r["test_seed"] == s])
                    for s in e["test_seeds"]
                ]
            )
        box = ax.boxplot(
            data,
            patch_artist=True,
            widths=0.48,
            showfliers=False,
            medianprops={"color": INK, "lw": 1.6},
            whiskerprops={"color": MUTED},
            capprops={"color": MUTED},
        )
        for patch, col in zip(box["boxes"], COL):
            patch.set(facecolor=col, alpha=0.24, edgecolor=col)
        for i, (vals, col) in enumerate(zip(data, COL)):
            ax.scatter(
                np.full(15, i + 1) + np.linspace(-0.12, 0.12, 15),
                vals,
                s=14,
                c=col,
                alpha=0.8,
                zorder=3,
            )
        ax.set(xticks=[1, 2, 3], xticklabels=["低通", "优化", "Q学习"], ylabel=ylabel)
        panel(ax, letter, "15个独立输入")
        style(ax)
    save(fig, out, "fig7_08_evaluation")
    fig, ax = plt.subplots(1, 2, figsize=(8.4, 4.4), layout="constrained")
    scs = e["scenarios"]
    sn = ["标称", "低初始能量", "容量/功率降额", "过载脉冲"]
    mat = np.array(
        [
            [
                np.mean(
                    [
                        r["rmse_kw"]
                        for r in e["metrics"]
                        if r["scenario"] == s and r["method"] == m
                    ]
                )
                for m in METHOD
            ]
            for s in scs
        ]
    )
    im = ax[0].imshow(mat, cmap="YlOrBr", vmin=0, vmax=20, aspect="auto")
    for i in range(4):
        for j in range(3):
            ax[0].text(
                j,
                i,
                f"{mat[i,j]:.2f}",
                ha="center",
                va="center",
                color="white" if mat[i, j] > 13 else INK,
                fontsize=11,
            )
    ax[0].set(
        xticks=range(3),
        xticklabels=["低通", "优化", "Q学习"],
        yticks=range(4),
        yticklabels=sn,
    )
    panel(ax[0], "(a)", "平均残差 RMSE / kW")
    fig.colorbar(im, ax=ax[0], shrink=0.8)
    for m, l, col in zip(METHOD, LABEL, COL):
        ax[1].plot(t, trace("overload", m, "residual_kw"), c=col, lw=1.4, label=l)
    ax[1].axvspan(210, 245, color=COL[2], alpha=0.1, label="追加需求区间")
    ax[1].set(xlim=(190, 265), xlabel="时间 / s", ylabel="残差功率 / kW")
    ax[1].legend(frameon=False, fontsize=8.5)
    panel(ax[1], "(b)", "保留过载段的完整残差")
    style(ax[1])
    save(fig, out, "fig7_09_robustness")


if __name__ == "__main__":
    main()
